GUARANTEE_TYPES = {"corporate_guarantee", "personal_guarantee"}


def plan_initial_securities(loan_model: Any) -> list[dict[str, Any]]:
    """One security per secured loan, from what is recorded today. Nothing is invented: rank,
    status, holder, valuation details and insurance stay empty; a guarantee gets no asset value."""
    rows: list[dict[str, Any]] = []
    for loan in loan_model.objects.all().order_by("created_at", "id"):
        if loan.collateral_type == "unsecured_exception":
            continue
        value = int(loan.collateral_value_minor or 0)
        rows.append(
            {
                "loan_id": loan.id,
                "position": 0,
                "security_type": loan.collateral_type,
                "description": loan.collateral_description or "",
                "value_minor": value
                if value > 0 and loan.collateral_type not in GUARANTEE_TYPES
                else None,
            }
        )
    return rows


def copy_current_securities(apps: Any, schema_editor: Any) -> None:
    loan_model = apps.get_model("loans", "Loan")
    security_model = apps.get_model("loans", "LoanSecurity")
    existing = set(security_model.objects.values_list("loan_id", flat=True))
    security_model.objects.bulk_create(
        [
            security_model(**row)
            for row in plan_initial_securities(loan_model)
            if row["loan_id"] not in existing
        ]
    )


